/* Familienküche v4 – familiengeschütztes Rezeptbuch, gemeinsame Daten und Kochassistent. */
(()=>{'use strict';
const RECIPES=window.RECIPES||[]; const BY_ID=new Map(RECIPES.map(r=>[r.id,r]));
const STORE='familienkueche.cloud.v2.'+window.FAMILY_CLOUD.user.id; const categories=[['alle','Alle'],['abend','Abendessen'],['brot','Brot'],['aufstrich','Aufstriche'],['hafer','Müsli & Porridge']];
const defaults={tab:'recipes',filter:'alle',cuisine:'alle',query:'',favoritesOnly:false,fav:{},cart:{},checked:{},custom:[],includeOptional:false,people:5,cook:null,timer:null,plans:[]};
function load(){try{const s=JSON.parse(localStorage.getItem(STORE)||'{}');return {...defaults,...s,tab:'recipes',query:'',filter:'alle',cuisine:'alle',favoritesOnly:false}}catch(e){return {...defaults}}}
let st={...load(),...window.CLOUD_INITIAL_STATE}, detailId=null, detailImageExpanded=false, detailServings=5, wakeLock=null, lastToast=null, searchTimer=null;
const main=document.getElementById('screen'),dialog=document.getElementById('dialog'),toastEl=document.getElementById('toast');
function save(){try{localStorage.setItem(STORE,JSON.stringify({...st,query:''}))}catch(e){}}
const h=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=n=>new Intl.NumberFormat('de-DE',{maximumFractionDigits:2}).format(Math.round((n+Number.EPSILON)*100)/100);
function amount(item,factor=1,forShopping=false){let n=(Number(item.qty)||0)*factor;let u=item.unit||'';if(forShopping&&['Stk','Zehe','Stange','Bund','Dose','Packung'].includes(u))n=Math.ceil(n-1e-9);return [fmt(n),u].filter(Boolean).join(' ')}
const img=r=>r.imageUrl && /^https:\/\/[^\s<>"']+$/i.test(r.imageUrl)?r.imageUrl:`images/${String(r.image||'rezept-neu.svg').replace(/[^a-zA-Z0-9_.-]/g,'')}`;
function flash(s){clearTimeout(lastToast);toastEl.textContent=s;toastEl.classList.add('show');lastToast=setTimeout(()=>toastEl.classList.remove('show'),2700)}
function changeTab(tab){if(!['recipes','shopping','plan','cook','settings'].includes(tab))return;closeDetail();st.tab=tab;save();render();window.scrollTo({top:0,behavior:'instant'})}
function useIcon(tag){return tag==='thermomix'?'⚙️':tag==='airfryer'?'♨️':tag==='vegetarisch'?'🌱':tag==='fisch'?'🐟':tag==='geflügel'?'🍗':'•'}
let shoppingDoneOpen=false;
function render({background=false}={}){const cookPanel=main.querySelector(".cook-details");const keepCookOpen=!!cookPanel?.open&&cookPanel.dataset.recipeId===st.cook?.id;const donePanel=document.getElementById("shoppingDone");if(donePanel)shoppingDoneOpen=donePanel.open;document.querySelectorAll('[data-nav]').forEach(b=>{let a=b.dataset.nav===st.tab;b.classList.toggle('active',a);b.setAttribute('aria-current',a?'page':'false')});let count=Object.keys(st.cart).filter(id=>BY_ID.has(id)).length;document.getElementById('cartCount').textContent=String(count);document.getElementById('cartCount').hidden=count===0;if(background&&st.tab==='cook')return;main.innerHTML=st.tab==='recipes'?recipesPage():st.tab==='shopping'?shoppingPage():st.tab==='plan'?planPage():st.tab==='cook'?cookPage():settingsPage();const nextCookPanel=main.querySelector(".cook-details");if(nextCookPanel&&keepCookOpen)nextCookPanel.open=true;updateTimerDisplays()}
function recipesPage(){const cuisines=[...new Set(RECIPES.filter(r=>st.filter==='alle'||r.category===st.filter).map(r=>r.cuisine))];const search=st.query.toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'');const list=RECIPES.filter(r=>(st.filter==='alle'||r.category===st.filter)&&(st.cuisine==='alle'||r.cuisine===st.cuisine)&&(!st.favoritesOnly||st.fav[r.id])&&((r.title+' '+r.description+' '+r.cuisine+' '+r.ingredients.map(x=>x.name).join(' ')).toLocaleLowerCase('de').normalize('NFD').replace(/[\u0300-\u036f]/g,'').includes(search)));
return `<div class="screen"><div class="page-intro"><div class="eyebrow">Für eure Familie · ohne Tomaten</div><div class="intro-row"><div><h1>Was kochen wir heute?</h1><p>${RECIPES.length} Rezeptideen mit Mengen, Einkaufsliste und Schritt-für-Schritt-Kochmodus.</p></div><div class="summary-pill">${RECIPES.length} Rezepte</div></div><section class="rc-launch"><div><strong>Eine neue Rezeptidee?</strong><p>Entwickle sie gemeinsam mit dem KI-Rezeptassistenten.</p></div><button class="btn btn-primary" data-action="open-recipe-chat">✦ Rezeptwerkstatt öffnen</button></section><label class="search-wrap"><svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/></svg><input type="search" id="recipeSearch" aria-label="Rezepte suchen" placeholder="Rezept oder Zutat suchen …" value="${h(st.query)}" autocomplete="off"></label></div><div class="chips" aria-label="Rezeptkategorien">${categories.map(([v,t])=>`<button class="chip ${st.filter===v?'active':''}" data-action="filter" data-val="${v}">${h(t)}</button>`).join('')}</div><div class="chips secondary-chips"><button class="chip ${st.cuisine==='alle'?'active':''}" data-action="cuisine" data-val="alle">Alle Küchen</button>${cuisines.map(v=>`<button class="chip ${st.cuisine===v?'active':''}" data-action="cuisine" data-val="${h(v)}">${h(v)}</button>`).join('')}</div><div class="results-line"><span>${list.length} ${list.length===1?'Rezept':'Rezepte'} gefunden</span><button class="text-button" data-action="favs">${st.favoritesOnly?'★ Nur Favoriten':'☆ Favoriten anzeigen'}</button></div>${list.length?`<div class="recipe-grid">${list.map(card).join('')}</div>`:`<div class="empty"><div class="empty-icon">🔎</div><strong>Keine Treffer</strong><p>Versuche einen anderen Suchbegriff oder setze die Filter zurück.</p><button class="btn btn-soft" data-action="reset-filter">Alle Rezepte anzeigen</button></div>`}<p class="footer-note">Rezeptbilder dienen der Illustration. Mengen sind Ausgangswerte und können angepasst werden. Alle Rezepte sind ohne Tomaten geplant; bei Fertigprodukten bitte die Zutatenliste prüfen.</p></div>`}
function nutritionDetails(r){const api=window.RECIPE_NUTRITION,n=api.estimate(r);return `<details class="notice nutrition-info"><summary class="nutrition-summary">Kalorien &amp; Nährwerte</summary><div class="nutrition-content"><strong>${h(api.label(r))}</strong>${n.complete?`<p>Für die gewählte Menge: ca. ${api.round(n.perServing*detailServings)} kcal insgesamt (ohne optionale Zutaten).</p>${n.optional>0?`<p>Mit allen optionalen Zutaten: ca. ${api.round(n.perServing+n.optionalPerServing)} kcal pro ${h(api.unit(r))}.</p>`:''}`:`<p>Für diese Zutaten fehlt eine verlässliche Zuordnung: ${n.missing.map(h).join(', ')}. Es wird kein unvollständiger Gesamtwert angezeigt.</p>`}${api.table(r)}<details><summary>Schätzung und Annahmen</summary><p>Grobe Berechnung aus üblichen Zutatenwerten, keine gemessenen oder produktspezifischen Nährwerte. Öl vollständig eingerechnet. Reis und Nudeln als Trockengewicht, Milch/Sojadrink mit Milch 1,5 %, Naturjoghurt mit 3,5 %, griechischer Joghurt mit 10 % Fett und Kokosmilch in der normalen Variante angesetzt. Bei Fladenbrot rechnen wir mit einem einzelnen Brot à 100 g; größere Brote erhöhen den Wert entsprechend. Brot/Ansatz meint die gesamte jeweilige Einheit, keine Scheibe oder kleine Aufstrichportion.</p>${n.assumptions.length?`<ul>${n.assumptions.map(x=>`<li>${h(x)}</li>`).join('')}</ul>`:''}</details></div></details>`}
function cardExcerpt(value){const text=String(value||'').replace(/\s+/g,' ').trim();if(text.length<=110)return text;const head=text.slice(0,111);const cut=head.lastIndexOf(' ');return head.slice(0,cut>70?cut:110).replace(/[ ,;:–-]+$/,'')+'…'}
function card(r){return `<article class="recipe-card"><div class="card-top"><button type="button" class="card-image-button" data-action="detail" data-id="${h(r.id)}" aria-label="Rezept öffnen: ${h(r.title)}"><img class="card-media" src="${img(r)}" loading="lazy" alt="${h(r.title)}"><span class="card-image-hint" aria-hidden="true">Rezept öffnen ↗</span></button><span class="card-category">${h(r.cuisine)}</span><button class="star ${st.fav[r.id]?'on':''}" data-action="favorite" data-id="${r.id}" aria-label="${st.fav[r.id]?'Favorit entfernen':'Als Favorit merken'}">${st.fav[r.id]?'★':'☆'}</button></div><div class="card-body"><div class="card-title">${h(r.title)}</div><p class="card-desc">${h(cardExcerpt(r.description))}</p><div class="card-meta"><span>◷ ${r.minutes} Min.</span><span>${r.servings} ${h(r.servingLabel)}</span>${r.tags.includes('thermomix')?'<span>⚙ TM6</span>':''}</div></div><div class="card-actions"><button class="btn btn-soft recipe-plan-button" data-action="recipe-plan" data-id="${h(r.id)}"><svg class="card-action-icon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><rect x="3" y="5" width="18" height="16" rx="2"/><path d="M16 3v4M8 3v4M3 11h18M12 14v4M10 16h4"/></svg><span>Planen</span></button><button class="btn ${st.cart[r.id]?'btn-soft':'btn-primary'}" data-action="add-cart" data-id="${r.id}">${st.cart[r.id]?'<svg class="card-action-icon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="m5 12 4 4L19 6"/></svg><span>Auf Liste</span>':'<svg class="card-action-icon" viewBox="0 0 24 24" width="18" height="18" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" focusable="false"><path d="M2 3h3l3 12h11l3-9H6M8 15l-1 3h12"/><circle cx="9" cy="21" r="1"/><circle cx="19" cy="21" r="1"/></svg><span>Einkaufsliste</span>'}</button><button class="btn btn-soft" data-action="detail" data-id="${r.id}">Rezept ansehen</button></div></article>`}
function chosenRecipes(){return Object.entries(st.cart).filter(([id,num])=>BY_ID.has(id)&&num>0).map(([id,num])=>({...BY_ID.get(id),wanted:num}))}
function aggregated(){let m=new Map();for(const r of chosenRecipes())for(const it of r.ingredients){if(it.optional&&!st.includeOptional)continue;const key=(it.name+'|'+it.unit).toLowerCase();if(!m.has(key))m.set(key,{...it,key,qty:0});m.get(key).qty+=it.qty*r.wanted/r.servings}
 const arr=[...m.values()];for(const el of st.custom||[]){let key='custom:'+el.id;arr.push({key,name:el.name,qty:el.qty,unit:el.unit,group:'Eigene Einträge',manual:true,id:el.id})}return arr.sort((a,b)=>a.group.localeCompare(b.group,'de')||a.name.localeCompare(b.name,'de'))}
function shoppingItemRow(it){return `<div class="shopping-item ${st.checked[it.key]?'checked':''}" data-action="check-item" data-key="${h(it.key)}" role="checkbox" aria-checked="${!!st.checked[it.key]}" tabindex="0"><span class="tickbox">${st.checked[it.key]?'✓':''}</span><span class="item-label">${h(it.name)}</span><span class="item-qty">${amount(it,1,true)}</span>${it.manual?`<button data-action="remove-custom" data-id="${h(it.id)}" class="text-button" aria-label="Eigene Zutat entfernen">✕</button>`:''}</div>`}
function shoppingPage(){const list=aggregated(),checkedItems=list.filter(x=>st.checked[x.key]),openItems=list.filter(x=>!st.checked[x.key]),done=checkedItems.length;let groups={};openItems.forEach(it=>(groups[it.group]??=[]).push(it));const sel=chosenRecipes();return `<div class="screen"><div class="page-intro"><div class="eyebrow">Ein Einkauf · mehrere Rezepte</div><h1>Unsere Einkaufsliste</h1><p>Gemeinsam für die ganze Familie: Gleiche Zutaten werden zusammengezählt, alle Häkchen und Artikel mit den Familiengeräten synchronisiert.</p></div><div class="soft-panel"><div class="intro-row"><strong>${sel.length} ${sel.length===1?'Rezept':'Rezepte'} ausgewählt</strong><span class="summary-pill">${done} von ${list.length} erledigt</span></div>${sel.length?`<div style="margin-top:12px">${sel.map(r=>`<div class="selected-recipe"><img class="mini-photo" src="${img(r)}" alt=""><div class="selected-main"><strong>${h(r.title)}</strong><small>${r.category==='brot'||r.category==='aufstrich'?h(r.servingLabel):'Portionen'}</small></div><div class="portion-control"><button data-action="cart-dec" data-id="${r.id}" aria-label="Menge verringern">−</button><strong>${r.wanted}</strong><button data-action="cart-inc" data-id="${r.id}" aria-label="Menge erhöhen">+</button></div><button class="text-button" data-action="cart-remove" data-id="${r.id}" aria-label="Rezept entfernen">✕</button></div>`).join('')}</div>`:`<div style="margin-top:10px" class="small-caption">Noch kein Rezept ausgewählt. Füge in „Rezepte“ Gerichte zur Einkaufsliste hinzu.</div><button style="margin-top:12px" class="btn btn-white" data-action="goto-recipes">Rezepte auswählen</button>`}<label class="toggle"><input type="checkbox" id="optionalCheck" ${st.includeOptional?'checked':''}> Optionale Rezeptzutaten mit einkaufen</label></div><div class="section-title"><h2>Einkaufen</h2><small>${openItems.length} offen</small></div>${openItems.length?Object.entries(groups).map(([name,its])=>`<section class="shopping-group"><div class="group-header"><strong>${h(name)}</strong><small>${its.length} Positionen</small></div>${its.map(shoppingItemRow).join('')}</section>`).join(''):list.length?`<div class="empty"><strong>Alles abgehakt!</strong><p>Alle Artikel findest du unten unter „Abgehakt“.</p></div>`:`<div class="empty"><div class="empty-icon">🛒</div><strong>Deine Liste ist noch leer</strong><p>Wähle Rezepte oder füge eigene Artikel hinzu.</p></div>`}${done?`<details id="shoppingDone" class="shopping-done" ${shoppingDoneOpen?'open':''}><summary>Abgehakt <span class="done-count">${done}</span></summary><p class="small-caption">Häkchen entfernen, um einen Artikel wieder nach oben zu verschieben.</p><div class="shopping-group">${checkedItems.map(shoppingItemRow).join('')}</div></details>`:''}<div class="section-title"><h2>Eigenen Artikel hinzufügen</h2></div><form id="customItem" class="section-card"><div class="field-row"><input class="field" required name="name" placeholder="z. B. Mineralwasser" maxlength="100" aria-label="Artikelname"></div><div class="field-row" style="margin-top:9px"><input class="field" name="qty" inputmode="decimal" placeholder="Menge, z. B. 2" aria-label="Menge"><select class="sel" name="unit"><option>Stk</option><option>g</option><option>ml</option><option>Packung</option><option>EL</option><option>TL</option></select><button type="submit" class="btn btn-primary">Hinzufügen</button></div></form><div class="shopping-actions"><button class="btn btn-primary" data-action="share-list">↗ Liste teilen / kopieren</button><button class="btn btn-white" data-action="uncheck-all">Alle abhaken zurücksetzen</button>${list.length?'<button class="btn btn-danger" data-action="clear-shopping">Liste leeren</button>':''}</div><p class="footer-note">Mengen verschiedener Einheiten werden nicht künstlich vermischt. Für Obst und Gemüse mit „Stk“ sind Größen nicht normiert. Einkaufsplanung funktioniert vollständig offline.</p></div>`}
function modeName(mode){return {hand:'Vorbereitung',topf:'Topf',ofen:'Backofen',pfanne:'Pfanne',tm6:'Thermomix TM6',airfryer:'Airfryer',kuehlschrank:'Kühlschrank'}[mode]||'Zubereitung'}
function cookPage(){let r=st.cook&&BY_ID.get(st.cook.id);if(!r){return `<div class="screen"><div class="page-intro"><div class="eyebrow">Schritt für Schritt</div><h1>Der Kochmodus</h1><p>Große Schritte, passende Zeiten und getrennte TM6-Anweisungen – wähle ein Rezept und starte.</p></div><div class="soft-panel" style="margin-bottom:18px"><strong>So funktioniert’s</strong><p style="margin-top:8px;color:var(--muted);line-height:1.5">1. Rezept wählen &nbsp; 2. Zutaten vorbereiten &nbsp; 3. Schritt für Schritt kochen. Timer sind optional und laufen, solange die App aktiv ist.</p></div><div class="recipe-grid">${RECIPES.filter(x=>x.category==='abend').slice(0,11).map(x=>`<article class="recipe-card"><img class="card-media" src="${img(x)}" alt=""><div class="card-body"><strong class="card-title">${h(x.title)}</strong><div class="card-meta">◷ ${x.minutes} Min.</div><button class="btn btn-primary btn-block" data-action="cook-start" data-id="${x.id}">Kochen starten</button></div></article>`).join('')}</div></div>`}
 if(st.cook.finished)return `<div class="cook-screen"><div class="cook-end"><div style="font-size:52px">🎉</div><h2>Guten Appetit!</h2><p>Du hast alle ${r.steps.length} Schritte für „${h(r.title)}“ durchlaufen.</p><button class="btn btn-primary btn-block" data-action="cook-finish">Zur Rezeptauswahl</button><button class="btn btn-white btn-block" style="margin-top:9px" data-action="cook-restart">Noch einmal kochen</button></div></div>`;
 let i=Math.min(st.cook.step,r.steps.length-1),step=r.steps[i],timer=st.timer,match=timer&&timer.recipeId===r.id&&timer.step===i;const progress=Math.round(i/r.steps.length*100);
 return `<div class="cook-screen"><div class="cook-title"><button class="back-link" data-action="cook-exit" aria-label="Kochmodus verlassen">←</button><div><small>Kochmodus · ${st.cook.servings} ${h(r.servingLabel)}</small><h2>${h(r.title)}</h2></div></div><div class="progress-track"><div class="progress-fill" style="width:${progress}%"></div></div><div class="cook-utilities"><span>${r.steps.length} Schritte · ${st.cook.servings} ${h(r.servingLabel)}</span><button class="text-button" data-action="wake">☼ Bildschirm wach halten</button></div><div class="step-indicator">Schritt ${i+1} von ${r.steps.length}</div><article class="cooking-card"><img class="cook-photo" src="${img(r)}" alt=""><div class="cook-body"><span class="mode-chip">${step.mode==='tm6'?'⚙️':step.mode==='airfryer'?'♨️':step.mode==='ofen'?'🔥':step.mode==='kuehlschrank'?'❄️':'🍳'} ${modeName(step.mode)}</span><h1>${h(step.title)}</h1><p class="step-description">${h(step.body)}</p>${step.minutes?`<div class="step-timer"><div><small>Timer für diesen Schritt</small><div class="timer-value" id="stepTimerValue">${match?timerFmt(timerRemaining(timer)):timerFmt(step.minutes*60)}</div></div><div class="timer-actions">${match&&timerRemaining(timer)>0?`<button data-action="timer-toggle">${timer.running?'Pause':'Weiter'}</button><button data-action="timer-reset">Reset</button>`:`<button data-action="timer-start" data-minutes="${step.minutes}">▶ Starten</button>`}</div></div>`:''}</div></article>${timer&&!match?`<div class="soft-panel" style="margin-top:13px">⏱ Timer aus Schritt ${timer.step+1}: <strong id="backgroundTimer">${timerFmt(timerRemaining(timer))}</strong> <button data-action="timer-toggle" class="text-button">${timer.running?'Pausieren':'Fortsetzen'}</button> <button data-action="timer-reset" class="text-button">Reset</button></div>`:''}<details class="cook-details" data-recipe-id="${h(r.id)}"><summary>🧺 Zutaten anzeigen (${r.ingredients.filter(x=>!x.optional).length})</summary>${r.ingredients.map((it,j)=>`<div class="ingredient-row ${st.cook.doneIngredients?.[j]?'checked':''}" data-action="cook-ingredient" data-idx="${j}" role="checkbox" aria-checked="${!!st.cook.doneIngredients?.[j]}"><span class="tickbox">${st.cook.doneIngredients?.[j]?'✓':''}</span><label>${h(it.name)} ${it.optional?'<small>(optional)</small>':''}</label><b>${amount(it,st.cook.servings/r.servings)}</b></div>`).join('')}</details><div class="jump-dots">${r.steps.map((x,j)=>`<button data-action="cook-jump" data-idx="${j}" class="${i===j?'on':''}" aria-label="Zu Schritt ${j+1}"></button>`).join('')}</div><div class="step-controls"><button class="btn btn-white btn-large" data-action="cook-prev" ${i===0?'disabled':''}>← Zurück</button><button class="btn btn-primary btn-large" data-action="cook-next">${i===r.steps.length-1?'✓ Fertig':'Weiter →'}</button></div><p class="footer-note">Timer im Browser sind kein verlässlicher Wecker, wenn das iPhone die App pausiert oder schließt. Längere Back- und Garzeiten am besten zusätzlich am Gerät absichern.</p></div>`}
function timerRemaining(t){return t.running?Math.max(0,Math.ceil((t.until-Date.now())/1000)):Math.max(0,t.remaining||0)}
function timerFmt(sec){sec=Math.max(0,Math.floor(sec));let hh=Math.floor(sec/3600),mm=Math.floor(sec%3600/60),ss=sec%60;return (hh?hh+':':'')+String(mm).padStart(2,'0')+':'+String(ss).padStart(2,'0')}
function updateTimerDisplays(){if(!st.timer)return;let txt=timerFmt(timerRemaining(st.timer));for(const n of ['stepTimerValue','backgroundTimer']){let el=document.getElementById(n);if(el)el.textContent=txt}}
function todayLocal(){const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function planPage(){return window.WEEK_PLAN.render(RECIPES,st.plans,st.people)}
function settingsPage(){const environment=location.protocol==='https:'?'HTTPS · PWA-Installation möglich':'HTTP/Datei · für den Einsatz HTTPS verwenden';return `<div class="screen"><div class="page-intro"><div class="eyebrow">Euer geschützter Bereich</div><h1>Einstellungen</h1><p>Rezeptbuch, Einkaufszettel und Essensplanung liegen sicher in der Familiendatenbank. Favoriten und Kochfortschritt bleiben nur auf diesem Gerät.</p></div><section class="section-card"><h3>Familienzugang</h3><p class="small-caption" style="margin-top:8px"><strong>${h(window.FAMILY_CLOUD.family.name||'Familienküche')}</strong><br>${h(window.FAMILY_CLOUD.user.email)} · ${window.FAMILY_CLOUD.family.role==='owner'?'Administrator':'Mitglied'}</p><div class="setting-actions"><button class="btn btn-soft" data-action="sync-now">↻ Jetzt synchronisieren</button><button class="btn btn-white" data-action="logout">Abmelden</button></div></section>${window.FAMILY_CLOUD.family.role==='owner'?`<section class="section-card" style="margin-top:15px"><h3>Benutzerverwaltung</h3><p class="small-caption" style="margin:8px 0 12px">Mitglieder mit E-Mail und Passwort hinzufügen oder ihren Familienzugang entfernen.</p><button class="btn btn-primary btn-block" data-action="open-user-admin">Benutzer verwalten</button></section><section class="section-card" style="margin-top:15px"><div class="eyebrow">Fernaktualisierung</div><h3>Rezepte verwalten</h3><p class="small-caption" style="margin:8px 0 12px">Vorhandene Rezepte suchen, bearbeiten oder löschen. Neue Rezepte als JSON importieren und für die Familie veröffentlichen.</p><button class="btn btn-primary btn-block" data-action="open-admin">✦ Rezeptverwaltung öffnen</button></section>`:``}<section class="section-card" style="margin-top:15px"><h3>Standardgröße der Familie</h3><p class="small-caption" style="margin-top:6px">Für den Kochmodus und neue Einkaufs- oder Planungseinträge.</p><div class="portion-control" style="margin-top:12px"><button data-action="people-dec">−</button><strong>${st.people}</strong><button data-action="people-inc">+</button></div><span style="font-size:12px;color:var(--muted);margin-left:10px">Personen</span></section><section class="section-card" style="margin-top:15px"><h3>Persönliches Backup</h3><p class="small-caption" style="margin-top:7px">Sichert nur Favoriten, Einstellungen und den persönlichen Kochfortschritt. Die Familien-Einkaufsliste und Planung sind bereits in Supabase gespeichert und werden beim Import nicht verändert.</p><div class="setting-actions"><button class="btn btn-soft" data-action="export">↓ Backup exportieren</button><label class="btn btn-white" style="position:relative;overflow:hidden">↑ Backup importieren<input id="importFile" type="file" accept="application/json,.json" style="position:absolute;inset:0;opacity:0;width:100%;cursor:pointer"></label></div></section><section class="section-card" style="margin-top:15px"><h3>iPhone und Offline-Nutzung</h3><div class="info-row"><div style="font-size:22px">📱</div><div><strong>App installieren</strong><p>Die HTTPS-Seite in Safari öffnen → Teilen → Zum Home-Bildschirm.</p></div></div><div class="info-row"><div style="font-size:22px">🔐</div><div><strong>Datenschutz</strong><p>Die Familienberechtigung wird bei jeder Datenbankabfrage mit Row Level Security geprüft. Bilder liegen als öffentliche statische Assets vor. Zugang und Rezepte selbst sind privat.</p></div></div><div class="info-row"><div style="font-size:22px">🔌</div><div><strong>Offline</strong><p>Bereits geöffnete Ansichten können zwischengespeichert sein. Ohne Netz sind neue Anmeldungen und Änderungen an gemeinsamen Daten nicht verfügbar. Timer im Browser sind kein zuverlässiger Hintergrundwecker.</p></div></div><div class="small-caption">${h(environment)}</div></section><section class="section-card" style="margin-top:15px"><h3>Wichtige Hinweise</h3><p class="small-caption" style="margin-top:6px">Rezepte sind ohne Tomaten angelegt. Allergene und Zutatenlisten selbst prüfen. Die App steuert keine Thermomix-Hardware.</p><button class="btn btn-danger" style="margin-top:16px" data-action="reset-data">Persönliche Einstellungen zurücksetzen</button></section><div class="footer-note">Familienküche · Cloud v4 · ${RECIPES.length} Familienrezepte</div></div>`}
function openDetail(id){let r=BY_ID.get(id);if(!r)return;detailId=id;detailImageExpanded=false;detailServings=st.cart[id]|| (r.category==='brot'||r.category==='aufstrich'?1:st.people);renderDetail();dialog.hidden=false;document.body.style.overflow='hidden'}
function renderDetail(){let r=BY_ID.get(detailId);if(!r)return;dialog.innerHTML=`<div class="dialog-panel" role="dialog" aria-modal="true" aria-label="Rezept ${h(r.title)}"><button class="dialog-close" data-action="close-dialog" aria-label="Schließen">×</button><button type="button" class="dialog-image-link ${detailImageExpanded?'is-expanded':''}" data-action="toggle-recipe-image" aria-expanded="${detailImageExpanded}" aria-label="${detailImageExpanded?'Bild verkleinern':'Bild vergrößern'}: ${h(r.title)}"><img src="${img(r)}" class="dialog-cover" alt="${h(r.title)}"><span class="dialog-image-hint">${detailImageExpanded?'Bild verkleinern −':'Bild vergrößern +'}</span></button><div class="dialog-content"><div class="eyebrow">${h(r.cuisine)} · ${h(r.category==='abend'?'Abendessen':r.category==='brot'?'Brot backen':r.category==='hafer'?'Mittagessen':'Aufstrich')}</div><h2>${h(r.title)}</h2><p class="detail-desc">${h(r.description)}</p><div class="detail-tags"><span class="tag">◷ ${r.minutes} Min.</span>${r.tags.map(t=>`<span class="tag">${useIcon(t)} ${h(t==='thermomix'?'TM6':t)}</span>`).join('')}</div><div class="section-title"><h3>Menge anpassen</h3><div class="portion-control"><button data-action="detail-dec">−</button><strong id="detailPortions">${detailServings}</strong><button data-action="detail-inc">+</button></div></div><p class="small-caption">Angaben für ${detailServings} ${h(r.servingLabel)}. Mengen werden rechnerisch skaliert.</p>${nutritionDetails(r)}<div class="section-title"><h3>Zutaten</h3><small>${r.ingredients.length} Einträge</small></div><div id="detailIngredientRows">${r.ingredients.map(it=>`<div class="ingredient-row"><label>${h(it.name)} ${it.optional?'<small>(optional)</small>':''}</label><b>${amount(it,detailServings/r.servings)}</b></div>`).join('')}</div><div class="section-title"><h3>Zubereitung</h3><small>${r.steps.length} Schritte</small></div>${r.steps.map((s,j)=>`<div class="detail-step"><div class="idx">${j+1}</div><div><strong>${h(s.title)} <span class="mini-count">${h(modeName(s.mode))}</span></strong><p>${h(s.body)}</p></div></div>`).join('')}${r.note?`<div class="notice">💡 ${h(r.note)}</div>`:''}</div><div class="sticky-detail-actions"><button class="btn btn-soft btn-large recipe-plan-button" data-action="detail-plan" data-id="${h(r.id)}">+ Einplanen</button><button class="btn btn-soft btn-large" data-action="detail-cart" data-id="${r.id}">+ Einkaufsliste</button><button class="btn btn-primary btn-large" data-action="cook-start" data-id="${r.id}">▶ Kochen</button></div></div>`}
function closeDetail(){dialog.hidden=true;dialog.innerHTML='';detailId=null;document.body.style.overflow=''}
function exportBackup(){const blob=new Blob([JSON.stringify({app:'Familienküche',version:1,exported:new Date().toISOString(),state:{fav:st.fav,cook:st.cook,timer:st.timer,people:st.people,includeOptional:st.includeOptional}},null,2)],{type:'application/json'});const link=document.createElement('a');link.href=URL.createObjectURL(blob);link.download='familienkueche-backup-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),500);flash('Backup exportiert')}
function listText(){const list=aggregated();const group=new Map();for(const it of list){if(!group.has(it.group))group.set(it.group,[]);group.get(it.group).push(it)}return 'FAMILIENKÜCHE · EINKAUFSLISTE\n\n'+[...group].map(([name,its])=>name+'\n'+its.map(it=>(st.checked[it.key]?'✓ ':'☐ ')+amount(it,1,true)+' '+it.name).join('\n')).join('\n\n')}
async function shareList(){let txt=listText();if(navigator.share){try{await navigator.share({title:'Einkaufsliste Familienküche',text:txt});return}catch(e){if(e.name==='AbortError')return}}
 if(navigator.clipboard&&navigator.clipboard.writeText){try{await navigator.clipboard.writeText(txt);flash('Einkaufsliste kopiert');return}catch(e){}}
 let ta=document.createElement('textarea');ta.value=txt;document.body.appendChild(ta);ta.select();let good=false;try{good=document.execCommand('copy')}catch(e){}ta.remove();flash(good?'Einkaufsliste kopiert':'Kopieren nicht unterstützt – bitte über HTTPS öffnen')}
async function toggleWakeLock(){if(wakeLock){await wakeLock.release();wakeLock=null;flash('Bildschirmsperre wieder normal');return}if(!navigator.wakeLock){flash('Bildschirm aktiv halten wird hier nicht unterstützt');return}try{wakeLock=await navigator.wakeLock.request('screen');flash('Bildschirm bleibt während des Kochens aktiv')}catch(e){flash('Bildschirmsperre konnte nicht deaktiviert werden')}}
function startCook(id,servings){let r=BY_ID.get(id);if(!r)return;if(st.cook&&!st.cook.finished&&st.cook.id!==id&&!confirm('Der bisherige Kochfortschritt wird ersetzt. Neues Rezept starten?'))return;st.cook={id,step:0,servings:servings||st.cart[id]|| (r.servings===1?1:st.people),doneIngredients:{},finished:false};st.timer=null;silenceTimerAlarm();closeDetail();changeTab('cook')}
function stopTimer(){dismissTimerAlarm();st.timer=null;silenceTimerAlarm();save()}
function doAction(el){const a=el.dataset.action,id=el.dataset.id,val=el.dataset.val;
if(a==='toggle-recipe-image'){detailImageExpanded=!detailImageExpanded;el.classList.toggle('is-expanded',detailImageExpanded);el.setAttribute('aria-expanded',String(detailImageExpanded));el.setAttribute('aria-label',(detailImageExpanded?'Bild verkleinern: ':'Bild vergrößern: ')+(BY_ID.get(detailId)?.title||''));el.querySelector('.dialog-image-hint').textContent=detailImageExpanded?'Bild verkleinern −':'Bild vergrößern +';return;}
if(new Set(['add-cart','detail-cart','cart-inc','cart-dec','cart-remove','check-item','remove-custom','uncheck-all','clear-shopping','plan-remove','plan-shop']).has(a)&&navigator.onLine===false){flash('Offline: Gemeinsame Daten können gerade nicht geändert werden.');return;}
if(a==='filter'){st.filter=val;st.cuisine='alle';save();render();return}if(a==='cuisine'){st.cuisine=val;save();render();return}if(a==='favs'){st.favoritesOnly=!st.favoritesOnly;render();return}if(a==='reset-filter'){st.query='';st.filter='alle';st.cuisine='alle';st.favoritesOnly=false;render();return}
if(a==='favorite'){st.fav[id]=!st.fav[id];save();render();return}if(a==='detail'){openDetail(id);return}if(a==='close-dialog'){closeDetail();return}if(a==='detail-inc'||a==='detail-dec'){detailServings=Math.max(1,Math.min(30,detailServings+(a==='detail-inc'?1:-1)));renderDetail();return}
if(a==='recipe-plan'||a==='detail-plan'){const r=BY_ID.get(id);if(!r)return;const servings=a==='detail-plan'?detailServings:st.cart[id]||(r.servings===1?1:st.people);const scrollX=window.scrollX,scrollY=window.scrollY;if(a==='detail-plan')closeDetail();window.WEEK_PLAN.openRecipe(id,servings,{recipes:RECIPES,plans:st.plans,people:st.people,onSaved(){flash('Rezept im Wochenplan gespeichert');const button=Array.from(document.querySelectorAll('[data-action="recipe-plan"]')).find(b=>b.dataset.id===id);button?.focus({preventScroll:true});window.scrollTo(scrollX,scrollY)}});return;}
if(a==='add-cart'||a==='detail-cart'){let r=BY_ID.get(id);if(!r)return;st.cart[id]=a==='detail-cart'?detailServings:st.cart[id]||(r.servings===1?1:st.people);window.FAMILY_CLOUD.upsertCart(id,st.cart[id]);save();if(a==='detail-cart')closeDetail();render();flash(a==='detail-cart'?'Menge zur Einkaufsliste übernommen':'Zur Einkaufsliste hinzugefügt');return}
if(a==='goto-recipes'){changeTab('recipes');return}if(a==='cart-inc'||a==='cart-dec'){let r=BY_ID.get(id);if(!r)return;st.cart[id]=Math.max(1,Math.min(30,st.cart[id]+(a==='cart-inc'?1:-1)));window.FAMILY_CLOUD.upsertCart(id,st.cart[id]);save();render();return}if(a==='cart-remove'){delete st.cart[id];st.checked={};window.FAMILY_CLOUD.removeCart(id);save();render();return}
if(a==='check-item'){st.checked[el.dataset.key]=!st.checked[el.dataset.key];window.FAMILY_CLOUD.setCheck(el.dataset.key,st.checked[el.dataset.key]);save();render();return}if(a==='remove-custom'){st.custom=st.custom.filter(c=>String(c.id)!==id);window.FAMILY_CLOUD.removeCustom(id);save();render();return}
if(a==='share-list'){shareList();return}if(a==='uncheck-all'){st.checked={};window.FAMILY_CLOUD.resetChecks();save();render();flash('Alle Häkchen zurückgesetzt');return}if(a==='clear-shopping'){if(confirm('Ausgewählte Rezepte und eigene Artikel aus der Einkaufsliste entfernen?')){st.cart={};st.custom=[];st.checked={};window.FAMILY_CLOUD.clearShopping();save();render()}return}
if(a==='plan-remove'){window.FAMILY_CLOUD.removePlan(id);st.plans=st.plans.filter(x=>x.id!==id);save();render();return}if(a==='plan-shop'){const num=Number(el.dataset.servings)||st.people;st.cart[id]=num;window.FAMILY_CLOUD.upsertCart(id,num);save();render();flash('Für die Familie auf der Einkaufsliste');return}if(a==='logout'){window.FAMILY_CLOUD.logout();return}if(a==='sync-now'){window.FAMILY_CLOUD.refresh();flash('Aktualisierung gestartet');return}
if(a==='open-admin'){window.RECIPE_ADMIN?.open();return}if(a==='people-inc'||a==='people-dec'){st.people=Math.max(1,Math.min(15,st.people+(a==='people-inc'?1:-1)));save();render();return}if(a==='open-settings'){changeTab('settings');return}if(a==='export'){exportBackup();return}if(a==='reset-data'){if(confirm('Wirklich alle Favoriten, Einkaufslisten und Kochfortschritte löschen?')){st={...defaults,...window.FAMILY_CLOUD.shared};save();render();flash('Persönliche Daten zurückgesetzt')}return}
if(a==='cook-start'){startCook(id,detailId===id?detailServings:undefined);return}if(a==='cook-exit'){changeTab('recipes');return}if(a==='cook-next'||a==='cook-prev'){if(!st.cook)return;let r=BY_ID.get(st.cook.id);if(a==='cook-next'&&st.cook.step===r.steps.length-1){st.cook.finished=true}else{st.cook.step=Math.min(r.steps.length-1,Math.max(0,st.cook.step+(a==='cook-next'?1:-1)))}save();render();window.scrollTo(0,0);return}if(a==='cook-jump'){st.cook.step=Number(el.dataset.idx);save();render();return}if(a==='cook-ingredient'){let idx=el.dataset.idx;st.cook.doneIngredients??={};st.cook.doneIngredients[idx]=!st.cook.doneIngredients[idx];save();const det=el.closest('details'),was=!!det?.open;render();let next=document.querySelector('.cook-details');if(next&&was)next.open=true;return}
if(a==='cook-finish'){st.cook=null;st.timer=null;silenceTimerAlarm();save();changeTab('recipes');flash('Rezept abgeschlossen');return}if(a==='cook-restart'){st.cook.step=0;st.cook.finished=false;st.cook.doneIngredients={};st.timer=null;silenceTimerAlarm();save();render();return}
if(a==='timer-start'){if(st.timer&&timerRemaining(st.timer)>0&&!confirm('Laufenden Timer durch neuen Timer ersetzen?'))return;dismissTimerAlarm();unlockTimerAudio();const dur=Number(el.dataset.minutes);st.timer={recipeId:st.cook.id,step:st.cook.step,remaining:dur*60,until:Date.now()+dur*60000,running:true};save();render();return}if(a==='timer-toggle'&&st.timer){if(st.timer.alarming){dismissTimerAlarm();render();return}unlockTimerAudio();if(st.timer.running){st.timer.remaining=timerRemaining(st.timer);st.timer.running=false}else{st.timer.until=Date.now()+st.timer.remaining*1000;st.timer.running=true}save();render();return}if(a==='timer-reset'){stopTimer();render();return}if(a==='wake'){toggleWakeLock();return}
}
document.addEventListener('click',e=>{const nav=e.target.closest('[data-nav]');if(nav){changeTab(nav.dataset.nav);return}const btn=e.target.closest('[data-action]');if(btn){e.preventDefault();doAction(btn)}});
dialog.addEventListener('click',e=>{if(e.target===dialog)closeDetail()});
document.addEventListener('input',e=>{if(e.target.id==='recipeSearch'){st.query=e.target.value;const start=e.target.selectionStart;clearTimeout(searchTimer);searchTimer=setTimeout(()=>{render();const input=document.getElementById('recipeSearch');input?.focus();input?.setSelectionRange(start,start)},160)}});
document.addEventListener('change',e=>{if(e.target.id==='optionalCheck'){st.includeOptional=e.target.checked;save();render()}else if(e.target.id==='importFile'){let f=e.target.files?.[0];if(!f)return;if(f.size>2e6){flash('Backup ist zu groß');return}f.text().then(txt=>{try{let data=JSON.parse(txt);if(data.app!=='Familienküche'||!data.state||typeof data.state!=='object')throw Error('Format');if(!confirm('Deine bisherige Einkaufsplanung und Favoriten durch das Backup ersetzen?'))return;let src=data.state;let validCart={};for(let [id,n] of Object.entries(src.cart||{})){if(BY_ID.has(id)&&Number.isFinite(+n))validCart[id]=Math.min(30,Math.max(1,Math.round(+n)))}let cooked=src.cook&&BY_ID.has(src.cook.id)&&Number.isInteger(src.cook.step)&&Number.isFinite(Number(src.cook.servings))?{id:src.cook.id,step:Math.max(0,Math.min(BY_ID.get(src.cook.id).steps.length-1,src.cook.step)),servings:Math.max(1,Math.min(30,Number(src.cook.servings))),doneIngredients:{},finished:!!src.cook.finished}:null;let fav={};for(const id of Object.keys(src.fav||{}))if(BY_ID.has(id))fav[id]=!!src.fav[id];st={...st,fav,people:Number.isInteger(src.people)?Math.max(1,Math.min(15,src.people)):5,includeOptional:!!src.includeOptional,cook:cooked,timer:null,tab:'recipes'};save();render();flash('Backup erfolgreich importiert')}catch(err){flash('Ungültiges Backup-Format')}})}});
document.addEventListener('submit',e=>{if(e.target.id==='planForm'){e.preventDefault();if(navigator.onLine===false){flash('Ohne Internet kann nichts im Familienplan geändert werden.');return;}const fd=new FormData(e.target);const recipe_id=String(fd.get('recipe_id')||'');const planned_on=String(fd.get('planned_on')||'');const servings=Number(fd.get('servings'));const meal_slot=String(fd.get('meal_slot')||'abend');if(!BY_ID.has(recipe_id)||!/^\d{4}-\d{2}-\d{2}$/.test(planned_on)||!Number.isInteger(servings)||servings<1||servings>30||!['mittag','abend'].includes(meal_slot)){flash('Bitte gültige Daten eingeben');return;}window.FAMILY_CLOUD.addPlan({recipe_id,planned_on,servings,meal_slot});flash('Eintrag wird gespeichert');return;}if(e.target.id!=='customItem')return;e.preventDefault();if(navigator.onLine===false){flash('Ohne Internet kann kein Familienartikel angelegt werden.');return;}const fd=new FormData(e.target);let name=String(fd.get('name')||'').trim();if(!name)return;let qty=Number(String(fd.get('qty')||'1').replace(',','.'));if(!Number.isFinite(qty)||qty<=0)qty=1;let item={id:'m'+Date.now().toString(36)+Math.random().toString(36).slice(2,5),name:name.slice(0,100),qty,unit:fd.get('unit')||'Stk'};st.custom.push(item);window.FAMILY_CLOUD.addCustom(item);save();render();flash('Artikel hinzugefügt')});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!dialog.hidden)closeDetail();if((e.key==='Enter'||e.key===' ')&&e.target.matches('[role="checkbox"][data-action]')){e.preventDefault();doAction(e.target)}});
// Reuse and unlock audio during a user gesture, before the timer expires.
let timerAudio=null, alarmLastBell=0;
const alarmVoices=new Set();
const alarmBanner=document.createElement('section');
alarmBanner.className='timer-alarm';alarmBanner.hidden=true;
alarmBanner.setAttribute('aria-label','Timer-Alarm');
alarmBanner.innerHTML='<div role="alert"><strong>⏱ Timer abgelaufen!</strong><p>Bitte bestätige den Alarm.</p></div><button type="button" class="btn btn-primary">Alarm stoppen</button>';
document.body.appendChild(alarmBanner);
alarmBanner.querySelector('button').addEventListener('click',()=>{dismissTimerAlarm();if(st.tab==='cook')render()});
function unlockTimerAudio(){try{if(!timerAudio)timerAudio=new (window.AudioContext||window.webkitAudioContext)();if(timerAudio.state==='suspended')timerAudio.resume().catch(()=>{});}catch(e){}}
function makeBell(){try{const ctx=timerAudio;if(!ctx||ctx.state!=='running')return;const o=ctx.createOscillator(),g=ctx.createGain();o.type='sine';o.frequency.value=830;g.gain.setValueAtTime(.16,ctx.currentTime);g.gain.exponentialRampToValueAtTime(.0001,ctx.currentTime+.6);o.connect(g);g.connect(ctx.destination);alarmVoices.add(o);o.onended=()=>{alarmVoices.delete(o);o.disconnect();g.disconnect()};o.start();o.stop(ctx.currentTime+.6)}catch(e){}}
function silenceTimerAlarm(){alarmBanner.hidden=true;alarmLastBell=0;for(const o of alarmVoices){try{o.stop()}catch(e){}}alarmVoices.clear()}
function dismissTimerAlarm(){if(st.timer)st.timer.alarming=false;save();silenceTimerAlarm()}
function checkTimerAlarm(){
 if(st.timer&&st.timer.running&&timerRemaining(st.timer)<=0){st.timer.remaining=0;st.timer.running=false;st.timer.alarming=true;save();if(st.tab==='cook')render()}
 if(st.timer?.alarming){alarmBanner.hidden=false;if(!alarmLastBell||Date.now()-alarmLastBell>=2000){makeBell();alarmLastBell=Date.now()}}
 else if(!alarmBanner.hidden)silenceTimerAlarm();
 updateTimerDisplays();
}
setInterval(checkTimerAlarm,1000);
document.addEventListener('visibilitychange',()=>{if(document.visibilityState==='visible')checkTimerAlarm()});
// A restored alarm can unlock sound on the next deliberate interaction too.
document.addEventListener('click',()=>{if(st.timer?.running||st.timer?.alarming)unlockTimerAudio()});
window.FAMILY_APP={applyRecipes(rows){RECIPES.splice(0,RECIPES.length,...rows);BY_ID.clear();for(const r of RECIPES)BY_ID.set(r.id,r);if(detailId&&!BY_ID.has(detailId))closeDetail();if(st.cook&&!BY_ID.has(st.cook.id)){st.cook=null;st.timer=null;silenceTimerAlarm();}render();flash('Rezeptbuch wurde aktualisiert')},applyShared(data){st.cart=data.cart;st.checked=data.checked;st.custom=data.custom;st.plans=data.plans;save();render({background:true})},notify:flash};
render();
})();
